def main():
    ap = argparse.ArgumentParser(
        description="Refine cell masks to polylines with MobileSAM"
    )
    ap.add_argument(
        "--weights_path", "--weights-path", dest="weights_path", type=str, required=True
    )
    ap.add_argument(
        "--output_path", "--output-path", dest="output_path", type=str, required=True
    )
    ap.add_argument(
        "--rgb_path", "--rgb-path", dest="rgb_path", type=str, required=True
    )
    ap.add_argument(
        "--csv_path", "--csv-path", dest="csv_path", type=str, required=True
    )
    args = ap.parse_args()

    torch.set_grad_enabled(False)
    device = "cpu"
